def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    import subprocess
    import os
    from itertools import islice
    from concurrent.futures import ThreadPoolExecutor

    if not cmd:
        raise ValueError("Command must be provided.")
    if target_concurrency < 1:
        raise ValueError("Target concurrency must be at least 1.")

    def run_command(args):
        try:
            result = subprocess.run(
                cmd + tuple(args),
                check=True,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=False,
                **kwargs
            )
            return result.returncode, result.stdout
        except subprocess.CalledProcessError as e:
            return e.returncode, e.output

    def chunked_varargs(varargs, n):
        it = iter(varargs)
        while True:
            chunk = list(islice(it, n))
            if not chunk:
                break
            yield chunk

    max_length = _max_length - sum(len(arg) for arg in cmd) - len(cmd) - 1
    if max_length <= 0:
        raise ValueError("Maximum command length is too small to accommodate the base command.")

    chunk_size = 1
    while True:
        test_chunk = list(islice(varargs, chunk_size))
        if not test_chunk:
            break
        test_command = cmd + tuple(test_chunk)
        if sum(len(arg) for arg in test_command) + len(test_command) - 1 > max_length:
            chunk_size -= 1
            break
        chunk_size += 1

    if chunk_size <= 0:
        raise ValueError("Individual arguments are too large to fit within the maximum command length.")

    results = []
    with ThreadPoolExecutor(max_workers=target_concurrency) as executor:
        future_to_args = {executor.submit(run_command, args): args for args in chunked_varargs(varargs, chunk_size)}
        for future in concurrent.futures.as_completed(future_to_args):
            try:
                return_code, output = future.result()
                results.append((return_code, output))
            except Exception as exc:
                results.append((1, str(exc).encode()))

    final_return_code = 0 if all(code == 0 for code, _ in results) else 1
    final_output = b''.join(output for _, output in results)
    return final_return_code, final_output

def parse_version(s: str) -> tuple[int, ...]:
