        parts = s.split('.')
        # Convert each part to an integer
        version_numbers = tuple(int(part) for part in parts)
        return version_numbers
    except ValueError:
        # Handle the case where conversion to integer fails
        raise ValueError("Version string contains non-integer parts")
    except AttributeError:
