def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    try:
        if not cmd:
            return cmd

        # Convert the command to a list for mutability
        cmd_list = list(cmd)

        # Check if the first element is a script with a shebang
        if cmd_list[0].endswith(('.py', '.pyw')):
            # Prepend 'python' to the command to ensure it's run with the Python interpreter
            cmd_list.insert(0, 'python')

        # Convert the list back to a tuple
        return tuple(cmd_list)

    except Exception as e:
        # Handle any unexpected exceptions
        print(f"An error occurred: {e}")
        return cmd

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            cache_key = key(*args, **kwargs)
            if lock:
                with lock:
                    if cache_key in cache:
                        return cache[cache_key]
                    result = func(*args, **kwargs)
                    cache[cache_key] = result
                    return result
            else:
                if cache_key in cache:
                    return cache[cache_key]
                result = func(*args, **kwargs)
                cache[cache_key] = result
                return result
        return wrapper
    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    from functools import lru_cache as _lru_cache

    if not isinstance(maxsize, int) or maxsize < 0:
        raise ValueError("maxsize must be a non-negative integer")
    if not isinstance(typed, bool):
        raise ValueError("typed must be a boolean")

    def decorator(func):
        return _lru_cache(maxsize=maxsize, typed=typed)(func)

    return decorator

