@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    try:
        if not isinstance(e, Exception):
            raise ValueError("The provided object is not an instance of Exception.")

        exc_type = type(e).__name__
        exc_message = str(e)
        formatted_traceback = []

        import traceback
        tb = traceback.extract_tb(e.__traceback__)

        for i, frame in enumerate(tb):
            if i >= max_level:
                break
            path_parts = frame.filename.split('/')
            path = '/'.join(path_parts[-max_path_level:])
            formatted_traceback.append(f"  File \"{path}\", line {frame.lineno}, in {frame.name}")
            if frame.line:
                formatted_traceback.append(f"    {frame.line.strip()}")

        return f"{exc_type}: {exc_message}\n" + "\n".join(formatted_traceback)

    except Exception as err:
        return f"Error formatting exception: {str(err)}"

