        default_schema = {}
        for resource in app.spec.manifest:
            if not isinstance(resource, dict) or 'kind' not in resource:
                continue

            kind = resource['kind']
            if kind not in app.observer_schema:
                default_schema[kind] = {
                    "metrics": {
                        "cpu_usage": "sum(rate(container_cpu_usage_seconds_total{container!='POD',pod=~'{}-.*'}[5m])) by (pod)".format(app.metadata.name),
                        "memory_usage": "sum(container_memory_usage_bytes{container!='POD',pod=~'{}-.*'}) by (pod)".format(app.metadata.name)
                    }
                }

        return default_schema

    except Exception as e:
        raise RuntimeError(f"Failed to generate default observer schema: {e}")

def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    try:
        if isinstance(params, Mapping):
            # Assuming named parameters
            out_params = {f":{key}": value for key, value in params.items()}
            formatted_sql = sql
            for key in params:
                placeholder = f":{key}"
                if placeholder in sql:
                    formatted_sql = formatted_sql.replace(f":{key}", f"@{key}")
            return formatted_sql, out_params
        elif isinstance(params, Sequence):
            # Assuming positional parameters
            out_params = [f"@p{i+1}" for i in range(len(params))]
            formatted_sql = sql
            for i in range(len(params)):
                placeholder = f"${i+1}"
                if placeholder in sql:
                    formatted_sql = formatted_sql.replace(placeholder, f"@p{i+1}")
            return formatted_sql, out_params
        else:
            raise ValueError("params must be a Mapping or Sequence")
    except Exception as e:
        raise ValueError(f"Error formatting SQL: {e}")

