def _extract_number_and_supplment_from_issue_element(issue):
    try:
        # Normalize the input by converting it to lowercase and removing extra spaces
        issue = issue.strip().lower().replace('  ', ' ')

        # Initialize variables to store the extracted number and supplement
        number = None
        supplement = None

        # Check for patterns that indicate a supplement
        if 'suppl' in issue or 'spe' in issue or 's' in issue:
            # Split the issue into parts
            parts = issue.split()

            # Extract the number if it exists
            if parts[0].isdigit() or (parts[0].startswith('s') and parts[0][1:].isdigit()):
                number = parts[0].lstrip('s')

            # Determine the supplement part
            if 'suppl' in issue:
                supplement = 'suppl'
            elif 'spe' in issue:
                supplement = 'spe'
            elif issue.startswith('s') and not issue.startswith('suppl'):
                supplement = 'spe'

            # Check for additional supplement details
            for part in parts[1:]:
                if part.isdigit() or part.replace('.', '', 1).isdigit():
                    supplement += ' ' + part
                elif part in ['pr', 'pr.']:
                    supplement += ' ' + part

        # Handle cases where the number is not at the start
        if number is None and any(part.isdigit() for part in issue.split()):
            for part in issue.split():
                if part.isdigit():
                    number = part
                    break

        return number, supplement
    except Exception as e:
        # Handle any unexpected errors
        print(f"An error occurred: {e}")
        return None, None

