def normalized(self):
    try:
        from dateutil.relativedelta import relativedelta
        days = int(self.days) + self.hours // 24
        hours = self.hours % 24 + self.minutes // 60
        minutes = self.minutes % 60 + self.seconds // 60
        seconds = self.seconds % 60 + self.microseconds // 1000000
        microseconds = self.microseconds % 1000000
        return relativedelta(days=days, hours=hours, minutes=minutes, seconds=seconds, microseconds=microseconds)
    except Exception as e:
        raise ValueError(f"Error normalizing relativedelta: {e}")

