def parse_arguments(*unparsed_arguments):
    import argparse

    parser = argparse.ArgumentParser(description='Process some command-line arguments.')
    subparsers = parser.add_subparsers(dest='subparser_name')

    # Example subparser
    parser_a = subparsers.add_parser('a', help='Subparser A')
    parser_a.add_argument('--foo', type=int, help='Foo argument for subparser A')

    # Example subparser
    parser_b = subparsers.add_parser('b', help='Subparser B')
    parser_b.add_argument('--bar', type=str, help='Bar argument for subparser B')

    # Global arguments
    parser.add_argument('--global_arg', type=str, help='Global argument')

    try:
        args = parser.parse_args(unparsed_arguments)
    except SystemExit:
        return {}

    result = {}
    if args.subparser_name:
        result[args.subparser_name] = args
    else:
        result['global'] = args

    return result

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_results = {}
    remaining_arguments = list(unparsed_arguments)

    for subparser_name, parser in subparsers.items():
        try:
            parsed_namespace, remaining = parser.parse_known_args(remaining_arguments)
            parsed_results[subparser_name] = parsed_namespace
            remaining_arguments = remaining
        except Exception as e:
            # Log the exception or handle it as needed
            print(f"Failed to parse arguments for subparser {subparser_name}: {e}")

    return parsed_results, remaining_arguments

