                    if k1.value == k2.value:
                        merged_value[i] = (k2, merge_values(k2, v1, v2))
                        found = True
                        break
                if not found:
                    merged_value.append((k2, v2))
            return MappingNode(tag=value1.tag, value=merged_value)
        else:
            return value2

    merged_dict = {}
    for key, value in nodes:
        if key.value in merged_dict:
            merged_dict[key.value] = merge_values(key, merged_dict[key.value], value)
        else:
            merged_dict[key.value] = value

    return [(ScalarNode(tag=key.tag, value=key_value), value) for key_value, value in merged_dict.items()]

def parse_arguments(*arguments):
