def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        mu = 0.2
        sigma = 0.1
        return (1 / (sigma * np.sqrt(2 * np.pi))) * np.exp(-0.5 * ((x - mu) / sigma) ** 2)
    except Exception as e:
        print(f"An error occurred: {e}")
        return None

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import logging
    import os
    import json

    if overrides is None:
        overrides = {}

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                config = json.load(file)
                if resolve_env:
                    config = {k: os.path.expandvars(v) if isinstance(v, str) else v for k, v in config.items()}
                config_dict[filename] = config
        except (FileNotFoundError, json.JSONDecodeError) as e:
            log_record = logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0,
                                         msg=str(e), args=(), exc_info=True)
            log_records.append(log_record)
        except Exception as e:
            log_record = logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0,
                                         msg=f"Unexpected error: {str(e)}", args=(), exc_info=True)
            log_records.append(log_record)

    # Apply overrides
    for key, value in overrides.items():
        for config in config_dict.values():
            if key in config:
                config[key] = value

    return config_dict, log_records

