def scale(self, other=None, recompute=False):
    if other is None:
        if not hasattr(self, '_scale') or recompute:
            self._scale = self._compute_scale()
        return self._scale
    else:
        if not isinstance(other, float):
            raise TypeError("The scale factor must be a float.")
        if self._scale == 0:
            raise LenaValueError("Cannot rescale a histogram with scale equal to zero.")
        self._scale = other

def scale(self, other=None):
    if other is None:
        if self._scale is None or self._scale == 0:
            raise LenaValueError("Graph has unknown or zero scale.")
        return self._scale
    else:
        if not isinstance(other, (int, float)):
            raise TypeError("Scale must be a numeric value.")
        if self._scale is None or self._scale == 0:
            raise LenaValueError("Graph has unknown or zero scale.")
        scale_factor = other / self._scale
        self._scale = other
        if self._fields:
            last_field = self._fields[-1]
            if last_field in self._data:
                self._data[last_field] = [x * scale_factor for x in self._data[last_field]]
            if 'errors' in self._data and last_field in self._data['errors']:
                self._data['errors'][last_field] = [x * scale_factor for x in self._data['errors'][last_field]]

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_: bin_

    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

    if len(field_names) != 2 + (1 if isinstance(make_value(bin_), tuple) and len(make_value(bin_)) > 1 else 0):
        raise ValueError("Number of field_names must match the dimension of the result")

    graph_points = []
    for bin_ in hist.bins:
        if get_coordinate == "left":
            x = bin_.left
        elif get_coordinate == "right":
            x = bin_.right
        elif get_coordinate == "middle":
            x = (bin_.left + bin_.right) / 2

        y_values = make_value(bin_)
        if not isinstance(y_values, tuple):
            y_values = (y_values,)

        point = {field_names[0]: x}
        for i, y in enumerate(y_values):
            point[field_names[i + 1]] = y

        graph_points.append(point)

    graph_scale = hist.scale if scale is True else scale

    return {"points": graph_points, "scale": graph_scale}

def _verify(iface, candidate, tentative=False, vtype=None):
    from zope.interface import providedBy, Invalid
    import inspect

    errors = []

    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"Candidate does not provide the interface {iface}")

    required_methods = set(method for name, method in iface.namesAndDescriptions() if inspect.isfunction(method))
    required_attributes = set(name for name, method in iface.namesAndDescriptions() if not inspect.isfunction(method))

    candidate_methods = set(name for name, _ in inspect.getmembers(candidate, predicate=inspect.ismethod))
    candidate_attributes = set(name for name, _ in inspect.getmembers(candidate, predicate=lambda a: not inspect.ismethod(a)))

    missing_methods = required_methods - candidate_methods
    if missing_methods:
        errors.extend(f"Missing method: {method}" for method in missing_methods)

    missing_attributes = required_attributes - candidate_attributes
    if missing_attributes:
        errors.extend(f"Missing attribute: {attr}" for attr in missing_attributes)

    for method_name in required_methods:
        if method_name in candidate_methods:
            iface_method = iface[method_name]
            candidate_method = getattr(candidate, method_name)
            iface_signature = inspect.signature(iface_method)
            candidate_signature = inspect.signature(candidate_method)
            if iface_signature != candidate_signature:
                errors.append(f"Method {method_name} has incorrect signature. Expected: {iface_signature}, Got: {candidate_signature}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

def verifyObject(iface, candidate, tentative=False):
    from zope.interface.exceptions import Invalid
    from zope.interface.verify import verifyObject as zope_verifyObject
    from zope.interface.verify import verifyClass
    from zope.interface.verify import verifyObject
    from zope.interface.verify import doesNotImplement
    import inspect

    errors = []

    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"Candidate does not claim to provide the interface {iface}")

    # Check methods
    for name in iface.names(all=True):
        if iface.get(name).queryTaggedValue('interface.method') is not None:
            if not hasattr(candidate, name):
                errors.append(f"Missing method: {name}")
            else:
                method = getattr(candidate, name)
                if not callable(method):
                    errors.append(f"Not callable: {name}")
                else:
                    iface_method = iface.get(name)
                    iface_method_signature = inspect.signature(iface_method)
                    candidate_method_signature = inspect.signature(method)
                    if iface_method_signature != candidate_method_signature:
                        errors.append(f"Method signature mismatch for {name}: expected {iface_method_signature}, got {candidate_method_signature}")

    # Check attributes
    for name in iface.names(all=True):
        if iface.get(name).queryTaggedValue('interface.attribute') is not None:
            if not hasattr(candidate, name):
                errors.append(f"Missing attribute: {name}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    try:
        if not isinstance(iface, type):
            raise ValueError("iface must be a class type")
        if not isinstance(candidate, type):
            raise ValueError("candidate must be a class type")

        if tentative:
            return issubclass(candidate, iface)
        else:
            return all(hasattr(candidate, attr) for attr in dir(iface) if not attr.startswith('__'))
    except Exception as e:
        print(f"An error occurred: {e}")
        return False

def determineMetaclass(bases, explicit_mc=None):
    if explicit_mc is not None:
        return explicit_mc
    for base in bases:
        if isinstance(base, type):
            return type(base)
    return type

def pop(self, key, default=__marker):
    if key in self:
        value = self[key]
        del self[key]
        return value
    elif default is not __marker:
        return default
    else:
        raise KeyError(key)

def _create_in_regex(self) -> Pattern:
    try:
        import re
        # The in-style parameter regex pattern
        # This pattern matches strings like 'in(value1,value2,value3)'
        pattern = r'in\(([^)]+)\)'
