def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    import re
    tags = set()
    code_block = False
    lines = text.split('\n')
    result_lines = []

    for line in lines:
        if line.strip().startswith('```'):
            code_block = not code_block
        if not code_block:
            tag_matches = re.findall(r'#(\w+)', line)
            for tag in tag_matches:
                tags.add(tag)
                if replacer:
                    line = re.sub(rf'#\b{tag}\b', replacer(tag), line)
        result_lines.append(line)

    return tags, '\n'.join(result_lines)

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if not isinstance(text, str):
        raise ValueError("Input must be a string")

    import re

    # Regular expression to find URLs
    url_pattern = re.compile(r'(https?://[^\s]+)')

    def linkify(match):
        url = match.group(0)
        return f'<a href="{url}" target="_blank" rel="noopener noreferrer">{url}</a>'

    try:
        processed_text = url_pattern.sub(linkify, text)
    except Exception as e:
        raise RuntimeError("An error occurred while processing the text") from e

    return processed_text

