        current = dic
        for k in (key,) + keys[:-1]:
            if k not in current or not isinstance(current[k], dict):
                current[k] = {}
            current = current[k]
        current[keys[-1]] = val
    except Exception as e:
        raise ValueError(f"An error occurred while inserting the value: {e}")

